ppendicular skeleton\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"boneIndex\",\n        \"label\": \"Bone/group index in the activity list\",\n        \"unit\": \"\",\n        \"min\": 0,\n        \"max\": 23,\n        \"default\": 0,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [\n      {\n        \"key\": \"view\",\n        \"default\": \"front\",\n        \"options\": [\n          \"front\",\n          \"back\"\n        ]\n      },\n      {\n        \"key\": \"division\",\n        \"default\": \"all\",\n        \"options\": [\n          \"all\",\n          \"axial\",\n          \"appendicular\"\n        ]\n      },\n      {\n        \"key\": \"labels\",\n        \"default\": \"on\",\n        \"options\": [\n          \"on\",\n          \"off\"\n        ]\n      },\n      {\n        \"key\": \"activity\",\n        \"default\": \"explore\",\n        \"options\": [\n          \"explore\",\n          \"identify\",\n          \"classify\"\n        ]\n      }\n    ],\n    \"protected\": false\n  }\n]\n", "src/lib/explorer/locales.ts": "import type { Language } from './catalog';\nexport const languageNames = { en: 'English', yo: 'Yorùbá', ha: 'Hausa', ig: 'Igbo' };\nexport const ui = {\n en: { heading:'Explore every topic', intro:'Find an existing simulation, read its explanation and open it with supported settings. No paid AI API is needed.', language:'Response language', topic:'Topic', automatic:'Detect from prompt', prompt:'Describe a topic or enter key=value settings', apply:'Explain and prepare', open:'Open simulation', defaults:'Default settings', settings:'Settings to apply', modes:'Simulation mode', manual:'Use this activity’s own controls for settings that are not listed here.', free:'Free rule-based demo · not generative AI', source:'Topic overview (English)', principle:'Key relation or principle', limitations:'This is an educational model. Check its assumptions and units. The explainer does not observe the running simulation.', protected:'This existing Minitab activity keeps its student login requirements.', detected:'Selected topic', error:'Unable to interpret this request.', noMatch:'Choose a topic or mention its name. This demo only opens existing registered activities.', invalid:'Some settings could not be interpreted. Use the exact keys and ranges shown below.', example:'Example prompt', attached:'Prepared settings', reference:'Related topics', close:'Hide explainer', review:'Change topic or settings', numerical:'Calculated result', supplied:'Requested values', omitted:'Omitted values keep the defaults below.', bridge:'Numeric preset handoff is available for the listed controls.', notes:'Scientific topic names and original activity text remain in English. Local-language explanations are draft teaching content for fluent-teacher review.' },\n yo: { heading:'Ṣe àyẹ̀wò gbogbo kókó', intro:'Wá simulation tó wà, ka àlàyé rẹ̀, kí o sì ṣí i pẹ̀lú àwọn ètò tí a ṣe àtìlẹ́yìn fún. Kò nílò API tí a ń sanwó fún.', language:'Èdè ìdáhùn', topic:'Kókó ẹ̀kọ́', automatic:'Yan láti inú ìbéèrè', prompt:'Sọ kókó kan tàbí kọ key=value', apply:'Ṣàlàyé kí o sì pèsè', open:'Ṣí simulation', defaults:'Àwọn iye àkọ́kọ́', settings:'Àwọn iye tí a ó lò', modes:'Mode simulation', manual:'Lo controls inú ìṣe náà fún àwọn ètò tí kò sí nínú àkójọ yìí.', free:'Àpẹẹrẹ ọ̀fẹ́ tó ń lo òfin · kì í ṣe AI tó ń dá ìdáhùn tuntun', source:'Àlàyé kókó (Gẹ̀ẹ́sì)', principle:'Ìbáṣepọ̀ tàbí òfin pàtàkì', limitations:'Àwòṣe ẹ̀kọ́ ni èyí. Ṣàyẹ̀wò àwọn àfojúsùn àti units rẹ̀. Olùṣàlàyé kò rí ohun tó ń ṣẹlẹ̀ nínú simulation.', protected:'Ìṣe Minitab yìí ṣì nílò student login tó wà tẹ́lẹ̀.', detected:'Kókó tí a yàn', error:'A kò lè túmọ̀ ìbéèrè yìí.', noMatch:'Yan kókó kan tàbí sọ orúkọ rẹ̀. Àpẹẹrẹ yìí ń ṣí àwọn ìṣe tí ó ti wà nìkan.', invalid:'A kò lè túmọ̀ díẹ̀ nínú àwọn iye. Lo keys àti ààlà tí a fi hàn nísàlẹ̀.', example:'Àpẹẹrẹ ìbéèrè', attached:'Àwọn iye tí a pèsè', reference:'Àwọn kókó tó jọra', close:'Pa àlàyé mọ́', review:'Yí kókó tàbí àwọn iye padà', numerical:'Àbájáde ìṣirò', supplied:'Àwọn iye tí o béèrè', omitted:'Iye tí o kò sọ yóò jẹ́ iye àkọ́kọ́ tó wà nísàlẹ̀.', bridge:'A lè fi àwọn iye ránṣẹ́ sí controls tí a ṣe àkójọ rẹ̀.', notes:'Àwọn orúkọ sáyẹ́ǹsì àti ọ̀rọ̀ inú ìṣe àtijọ́ ṣì wà ní Gẹ̀ẹ́sì. Kí olùkọ́ tó mọ èdè náà ṣàyẹ̀wò ìtumọ̀ kí a tó lò ó ní kíláàsì.' },\n ha: { heading:'Binciki dukkan batutuwa', intro:'Nemo simulation da yake akwai, karanta bayaninsa, sannan buɗe shi da saitunan da ake goyon baya. Ba a buƙatar API mai kuɗi.', language:'Harshen amsa', topic:'Batun darasi', automatic:'Zaɓa daga tambaya', prompt:'Bayyana batu ko rubuta key=value', apply:'Bayyana kuma shirya', open:'Buɗe simulation', defaults:'Saitunan farko', settings:'Saitunan da za a yi amfani da su', modes:'Yanayin simulation', manual:'Yi amfani da controls na aikin don saitunan da ba a lissafa a nan ba.', free:'Samfurin kyauta mai ƙa’idoji · ba AI mai samar da sabbin amsoshi ba', source:'Bayani kan batu (Turanci)', principle:'Muhimmiyar alaƙa ko ƙa’ida', limitations:'Wannan samfurin koyarwa ne. Duba sharuɗɗansa da units. Mai bayanin ba ya ganin abin da ke faruwa a simulation.', protected:'Wannan aikin Minitab yana riƙe buƙatar student login ɗinsa.', detected:'Batun da aka zaɓa', error:'An kasa fahimtar wannan buƙata.', noMatch:'Zaɓi batu ko rubuta sunansa. Samfurin yana buɗe ayyukan da aka riga aka yi rajista kawai.', invalid:'An kasa fahimtar wasu saituna. Yi amfani da keys da iyakokin da aka nuna a ƙasa.', example:'Misalin tambaya', attached:'Saitunan da aka shirya', reference:'Batutuwa masu alaƙa', close:'Ɓoye bayani', review:'Sauya batu ko saituna', numerical:'Sakamakon lissafi', supplied:'Ƙimomin da aka nema', omitted:'Abin da ba a bayyana ba yana riƙe ma’aunin farko da ke ƙasa.', bridge:'Ana iya aika ƙimomi zuwa controls da aka lissafa.', notes:'Sunayen kimiyya da rubutun ayyukan asali suna da Turanci. Malamin fannin da ya iya harshen ya duba fassarar kafin amfani a aji.' },\n ig: { heading:'Nyochaa isiokwu niile', intro:'Chọta simulation dị adị, gụọ nkọwa ya, ma mepee ya na ntọala akwadoro. Ọ chọghị API a na-akwụ ụgwọ.', language:'Asụsụ azịza', topic:'Isiokwu', automatic:'Chọpụta site n’arịrịọ', prompt:'Kọwaa isiokwu ma ọ bụ dee key=value', apply:'Kọwaa ma kwadebe', open:'Mepee simulation', defaults:'Ntọala mbido', settings:'Ntọala a ga-etinye', modes:'Ụdị simulation', manual:'Jiri controls nke ọrụ ahụ maka ntọala ndị a na-edeghị ebe a.', free:'Ihe ngosi efu na-eji iwu · ọ bụghị AI na-emepụta azịza ọhụrụ', source:'Nkọwa isiokwu (Bekee)', principle:'Mmekọrịta ma ọ bụ iwu bụ isi', limitations:'Nke a bụ ihe nlereanya mmụta. Lelee ọnọdụ na units ya. Onye nkọwa anaghị ahụ simulation na-agba.', protected:'Ọrụ Minitab a ka na-achọ student login ya.', detected:'Isiokwu ahọpụtara', error:'Aghọtaghị arịrịọ a.', noMatch:'Họrọ isiokwu ma ọ bụ dee aha ya. Ihe ngosi a na-emepe naanị ọrụ ndị e debanyere aha.', invalid:'Aghọtaghị ụfọdụ ntọala. Jiri keys na oke ndị e gosiri n’okpuru.', example:'Ihe atụ arịrịọ', attached:'Ntọala akwadoro', reference:'Isiokwu ndị metụtara ya', close:'Zoo nkọwa', review:'Gbanwee isiokwu ma ọ bụ ntọala', numerical:'Nsonaazụ mgbakọ', supplied:'Ụkpụrụ a rịọrọ', omitted:'Ihe a na-akọwaghị ga-eji ntọala mbido dị n’okpuru.', bridge:'Enwere ike iziga ụkpụrụ na controls ndị e depụtara.', notes:'Aha sayensị na ederede ọrụ mbụ ka dị na Bekee. Onye nkuzi maara asụsụ na ihe ọmụmụ ahụ kwesịrị inyocha nsụgharị tupu iji ya n’ụlọ akwụkwọ.' },\n};\n// Overview concepts supplement, rather than claim to translate, the original English activities.\nconst concepts: Record<string,[string,string,string]> = {\n skeleton:['Egungun ń gbé ara dúró, ó ń dáàbò bo àwọn ẹ̀yà ara, ó sì ń ran ìṣípò lọ́wọ́. Àgbàlagbà sábà ní egungun 206: 80 axial àti 126 appendicular. Yan egungun kan kí o ka ibi àti iṣẹ́ rẹ̀.','Ƙasusuwan jiki suna tallafa wa jiki, suna kare gaɓobin ciki kuma suna taimaka wa motsi. Yawanci babban mutum yana da ƙasusuwa 206: 80 axial da 126 appendicular. Zaɓi ƙashi don koyon inda yake da aikinsa.','Ọkpụkpụ na-akwado ahụ, na-echebe akụkụ ahụ dị n’ime ma na-enyere mmegharị aka. Okenye na-enwekarị ọkpụkpụ 206: 80 axial na 126 appendicular. Họrọ ọkpụkpụ ka ị mụta ebe ọ dị na ọrụ ya.'],\n force:['Net force ló ń fa acceleration; bí mass bá pọ̀ sí i fún force kan náà, acceleration yóò dín kù.','Ƙarfin net force yana haifar da acceleration; idan mass ya ƙaru a force ɗaya, acceleration yana raguwa.','Net force na-ebute acceleration; ma mass bawanye na force otu, acceleration na-ebelata.'],\n circuit:['Voltage, current àti resistance ní ìbáṣepọ̀. Òfin Ohm kan ohmic conductor ní ipò ara tó dúró ṣinṣin.','Voltage, current da resistance suna da alaƙa. Dokar Ohm tana aiki ga ohmic conductor a yanayin jiki da bai sauya ba.','Voltage, current na resistance nwere mmekọrịta. Iwu Ohm na-arụ ọrụ maka ohmic conductor mgbe ọnọdụ anụ ahụ ya anaghị agbanwe.'],\n wave:['Wave ń gbé agbára. Frequency àti wavelength ló pinnu speed nípasẹ̀ v = fλ.','Wave yana ɗaukar makamashi. Frequency da wavelength suna da alaƙa da speed ta v = fλ.','Wave na-ebufe ike. Frequency na wavelength jikọtara speed site na v = fλ.'],\n projectile:['Ya velocity sí apá petele àti inárọ̀; gravity ń yí apá inárọ̀ padà. Àwòṣe yìí kò ka ìdènà afẹ́fẹ́ sí.','Raba velocity zuwa na kwance da na tsaye; gravity yana sauya na tsaye. Wannan samfurin yana yin watsi da juriyar iska.','Kewaa velocity n’akụkụ kwụ ọtọ n’ala na nke elu; gravity na-agbanwe akụkụ elu. Ihe nlereanya a na-eleghara mgbochi ikuku anya.'],\n oscillation:['Ìṣípò tó ń padà sẹ́yìn àti síwájú ni oscillation. Mass, restoring force àti damping lè yí ìṣípò rẹ̀ padà.','Oscillation motsi ne na kai-komo. Mass, restoring force da damping na iya sauya motsin.','Oscillation bụ mmegharị azụ na ihu. Mass, restoring force na damping nwere ike ịgbanwe mmegharị ya.'],\n quantum:['Ní quantum physics, àwọn iye agbára lè wà ní ìpele pàtó. Àwòṣe àti àwọn ààlà rẹ̀ gbọ́dọ̀ hàn gbangba.','A quantum physics, makamashi na iya kasancewa a matakai na musamman. A bayyana samfurin da iyakokinsa.','Na quantum physics, ike nwere ike ịdị n’ọkwa a kapịrị ọnụ. A ghaghị ịkọwa ihe nlereanya na oke ya.'],\n atom:['Iye proton ló ń dá element mọ̀. Àwòṣe atom ń ràn wá lọ́wọ́ láti ṣàlàyé ẹ̀rí, kì í ṣe fọ́tò atom gidi.','Adadin proton yana gane element. Samfurin atom yana taimaka wajen bayyana shaida, ba hoton atom na gaske ba ne.','Ọnụọgụ proton na-egosi element. Ihe nlereanya atom na-enyere aka ịkọwa ihe akaebe; ọ bụghị foto atom n’eziokwu.'],\n chemistry:['Ìpín atom àti bí wọ́n ṣe so pọ̀ ṣe pàtàkì. Kíkọ formula nìkan kò fi hàn pé compound wà tàbí pé ó dúró ṣinṣin.','Rabon atoms da yadda suka haɗu suna da muhimmanci. Formula kaɗai ba ya tabbatar da wanzuwa ko kwanciyar compound.','Oke atoms na otú ha si jikọta dị mkpa. Formula naanị anaghị egosi na compound dị adị ma ọ bụ kwụsiri ike.'],\n crystal:['Àtòjọ atom àti àwọn ibi tí wọ́n jókòó ṣe pàtàkì nínú crystal. Geometric screening kò tó láti fi stability hàn.','Tsarin atoms da wurarensu suna da muhimmanci a crystal. Geometric screening kaɗai ba ya tabbatar da stability.','Nhazi atoms na ebe ha nọ dị mkpa na crystal. Geometric screening naanị anaghị egosi stability.'],\n decay:['Half-life ni àkókò tí iye tó kù ń dín sí ìdajì ní ìsúnmọ́ ìṣirò. Decay atom kọ̀ọ̀kan jẹ́ ohun tó dá lórí probability.','Half-life shi ne lokacin da adadin da ake sa ran zai rage ya koma rabi. Decay na atom guda yana da probability.','Half-life bụ oge ọnụọgụ a na-atụ anya ka fọdụrụ ga-ebelata ọkara. Decay nke atom ọ bụla dabere na probability.'],\n vector:['Vector ní magnitude àti direction. Ya a sí components kí o tó ṣe ìṣirò tí ó bá yẹ.','Vector yana da magnitude da direction. Raba shi zuwa components idan hakan ya dace da lissafi.','Vector nwere magnitude na direction. Kewaa ya na components mgbe ọ dị mkpa maka mgbakọ.'],\n trig:['Lórí unit circle, cosine ni x-coordinate, sine sì ni y-coordinate. Ṣàyẹ̀wò boya degree tàbí radian ni a ń lò.','A unit circle, cosine shi ne x-coordinate, sine kuma y-coordinate. Duba ko ana amfani da degrees ko radians.','Na unit circle, cosine bụ x-coordinate, sine bụ y-coordinate. Lelee ma a na-eji degrees ma ọ bụ radians.'],\n gas:['Pressure, volume àti temperature ní ìbáṣepọ̀. Lo temperature ní kelvin nínú ideal gas equation.','Pressure, volume da temperature suna da alaƙa. Yi amfani da temperature a kelvin a ideal gas equation.','Pressure, volume na temperature nwere mmekọrịta. Jiri temperature dị na kelvin n’ime ideal gas equation.'],\n heat:['Agbára ń sàn láti ibi tó gbóná sí ibi tó tutù. Material àti geometry ń ní ipa lórí iyára gbigbe ooru.','Makamashi yana gudana daga wuri mai zafi zuwa mai sanyi. Material da geometry suna shafar saurin canja zafi.','Ike na-esi ebe dị ọkụ gaa ebe dị oyi. Material na geometry na-emetụta ọsọ mbufe okpomọkụ.'],\n friction:['Static friction lè yí padà títí dé ààlà rẹ̀. Kinetic friction ń tako relative sliding.','Static friction na iya sauyawa har zuwa iyakarsa. Kinetic friction yana adawa da zamewar abubuwa.','Static friction nwere ike ịgbanwe ruo n’oke ya. Kinetic friction na-egbochi ịmịgharị ihe n’elu ibe ya.'],\n equilibrium:['Fún static equilibrium, net force àti net turning effect gbọ́dọ̀ jẹ́ odo.','A static equilibrium, net force da net turning effect su zama sifili.','Maka static equilibrium, net force na net turning effect ga-abụ efu.'],\n elastic:['Nínú proportional limit, force àti extension ń pọ̀ sí i ní ìpín kan náà. Kọjá ààlà yìí lè yí ìhùwàsí padà.','A cikin proportional limit, force da extension suna ƙaruwa a rabo ɗaya. Bayan wannan iyaka hali na iya sauyawa.','N’ime proportional limit, force na extension na-abawanye n’otu oke. Mgbe e gafere oke ahụ, omume nwere ike ịgbanwe.'],\n induction:['Ìyípadà magnetic flux linkage ló ń fa induced voltage. Direction rẹ̀ ń tako ìyípadà tó fa a.','Sauyin magnetic flux linkage yana haifar da induced voltage. Direction ɗinsa yana adawa da sauyin da ya haifar da shi.','Mgbanwe magnetic flux linkage na-ebute induced voltage. Direction ya na-emegide mgbanwe kpatara ya.'],\n charge:['Charge ń ṣẹ̀dá electric field; àwọn field sì lè darapọ̀. Àmì charge ṣe pàtàkì fún direction force.','Charge yana samar da electric field, kuma fields na iya haɗuwa. Alamar charge tana da muhimmanci ga direction na force.','Charge na-emepụta electric field, fields nwekwara ike ijikọta. Akara charge dị mkpa maka direction force.'],\n capacitor:['Capacitance so charge pọ̀ mọ́ potential difference. Geometry àti ohun tó wà láàárín plates ń ní ipa.','Capacitance yana haɗa charge da potential difference. Geometry da abin da ke tsakanin plates suna da tasiri.','Capacitance jikọtara charge na potential difference. Geometry na ihe dị n’etiti plates na-emetụta ya.'],\n magnetic:['Electric current lè ṣẹ̀dá magnetic field. Force lórí conductor sinmi lórí field, current àti direction.','Electric current na iya samar da magnetic field. Force a conductor ya dogara da field, current da direction.','Electric current nwere ike ịmepụta magnetic field. Force n’elu conductor dabere na field, current na direction.'],\n reflection:['Ní reflection, igun tí ray fi wọlé dọ́gba pẹ̀lú igun tí ó fi padà, a sì ń wọn wọn láti normal.','A reflection, kusurwar shigowa tana daidai da ta dawowa; ana auna su daga normal.','Na reflection, nkuku mbata hà nkuku nlọghachi; a na-atụ ha site na normal.'],\n refraction:['Ray lè yí direction padà ní ààlà media. Refractive indices àti igun ló pinnu ìbáṣepọ̀ Snell.','Ray na iya sauya direction a iyakar media. Refractive indices da kusurwoyi suna bin dokar Snell.','Ray nwere ike ịgbanwe direction n’ókè media. Refractive indices na nkuku na-agbaso iwu Snell.'],\n optics:['Ray model ń lo ìlà tó tọ́ nínú uniform medium láti ṣàlàyé òjìji àti image.','Ray model yana amfani da madaidaiciyar hanya a uniform medium don bayyana inuwa da image.','Ray model na-eji ụzọ kwụ ọtọ n’ime uniform medium ịkọwa onyinyo na image.'],\n polarization:['Polarizer ń yan direction electric-field vibration. Bí igun àwọn polarizer ṣe yàtọ̀ ń yí intensity padà.','Polarizer yana zaɓar direction na electric-field vibration. Bambancin kusurwa yana sauya intensity.','Polarizer na-ahọrọ direction electric-field vibration. Ọdịiche nkuku na-agbanwe intensity.'],\n semiconductor:['Àwọn carrier àti bias ń ní ipa lórí conduction nínú semiconductor.','Carriers da bias suna shafar conduction a semiconductor.','Carriers na bias na-emetụta conduction na semiconductor.'],\n transistor:['Bias tó wà ní terminal ń darí conduction. Ṣàyẹ̀wò mode àti àwọn àfojúsùn device model.','Bias a terminals yana sarrafa conduction. Duba mode da sharuɗɗan device model.','Bias na terminals na-achịkwa conduction. Lelee mode na ọnọdụ device model.'],\n band:['Energy bands àti carrier population ń ràn wá lọ́wọ́ láti ṣàlàyé electrical conduction.','Energy bands da yawan carriers suna taimakawa wajen bayyana electrical conduction.','Energy bands na ọnụọgụ carriers na-enyere aka ịkọwa electrical conduction.'],\n earth:['Àwọn layer Earth àti atmosphere ní properties tó yàtọ̀. Àwòṣe yìí jẹ́ ohun ìrànwọ́ ẹ̀kọ́.','Layers na Earth da atmosphere suna da properties daban-daban. Wannan samfurin kayan koyarwa ne.','Layers nke Earth na atmosphere nwere properties dị iche iche. Ihe nlereanya a bụ enyemaka mmụta.'],\n geophysics:['Àwọn signal physics lè fún wa ní ẹ̀rí nípa abẹ́ ilẹ̀. Ọ̀pọ̀ model lè ṣàlàyé data kan náà.','Signals na physics na iya ba da shaida kan ƙarƙashin ƙasa. Models da yawa na iya bayyana data ɗaya.','Signals physics nwere ike inye ihe akaebe gbasara ihe dị n’okpuru ala. Models dị iche iche nwere ike ịkọwa otu data.'],\n solar:['Gravity ń darí orbit. Fún àwọn ohun tó ń yí central mass kan náà ká, T² ní ìbáṣepọ̀ pẹ̀lú a³.','Gravity yana sarrafa orbit. Ga abubuwan da ke zagaya central mass ɗaya, T² yana da alaƙa da a³.','Gravity na-achịkwa orbit. Maka ihe ndị na-agba otu central mass gburugburu, T² jikọtara a³.'],\n tectonics:['Plate motion ń so àwọn àpẹẹrẹ lórí ilẹ̀ pọ̀ mọ́ geological processes.','Plate motion yana haɗa tsarin saman ƙasa da geological processes.','Plate motion jikọtara usoro elu ala na geological processes.'],\n calculus:['Derivatives ń ṣàlàyé ìyípadà agbègbè kékeré; integrals ń kó àwọn ipa kékeré jọ.','Derivatives suna bayyana sauyi na gida; integrals suna tara ƙananan tasiri.','Derivatives na-akọwa mgbanwe mpaghara nta; integrals na-achịkọta obere mmetụta.'],\n matrix:['Eigenvector ń pa direction rẹ̀ mọ́ lábẹ́ linear transformation, àfi scaling.','Eigenvector yana riƙe direction ɗinsa ƙarƙashin linear transformation sai dai scaling.','Eigenvector na-edobe direction ya n’okpuru linear transformation, ma scaling nwere ike ịgbanwe.'],\n fourier:['A lè tú signal sí àwọn frequency components láti lóye ìṣètò rẹ̀.','Ana iya raba signal zuwa frequency components don fahimtar tsarinsa.','Enwere ike ikewa signal na frequency components iji ghọta nhazi ya.'],\n special:['Special functions ń farahàn nínú equations physics àti mathematics. Àwọn ààlà problem ló ń yan solution tó yẹ.','Special functions suna bayyana a equations na physics da mathematics. Boundary conditions suna zaɓar solution da ya dace.','Special functions na-apụta n’equations physics na mathematics. Boundary conditions na-ahọrọ solution kwesịrị ekwesị.'],\n};\nexport function conceptExplanation(concept:string, language:Language, english:string) { return language==='en' ? english : concepts[concept]?.[{yo:0,ha:1,ig:2}[language]] || english; }\n", "src/components/explorer/TopicPicker.tsx": "'use client';\nimport { useEffect, useId, useRef, useState } from 'react';\nimport { topics, getTopic } from '@/lib/explorer/catalog';\n\ntype Props = { value: string; onChange: (id: string) => void; label: string; automatic: string };\nexport function TopicPicker({ value, onChange, label, automatic }: Props) {\n const [open, setOpen] = useState(false), [query, setQuery] = useState('');\n const dialog = useRef<HTMLDialogElement>(null), search = useRef<HTMLInputElement>(null), trigger = useRef<HTMLButtonElement>(null);\n const titleId = useId();\n const selected = getTopic(value);\n const filtered = topics.filter(t => `${t.title} ${t.subject}`.toLowerCase().includes(query.trim().toLowerCase()));\n const colours = { color: '#111827', backgroundColor: '#fff', colorScheme: 'light' as const };\n useEffect(() => {\n  const el = dialog.current; if (!el) return;\n  if (open) { if (!el.open) el.showModal(); search.current?.focus(); }\n  else if (el.open) el.close();\n }, [open]);\n function close() { setOpen(false); trigger.current?.focus(); }\n function choose(id: string) { onChange(id); close(); }\n return <div className=\"min-w-0 text-xs font-semibold text-gray-800\" style={colours}>\n  <span>{label}</span>\n  <button ref={trigger} type=\"button\" aria-haspopup=\"dialog\" aria-expanded={open} onClick={() => { setQuery(''); setOpen(true); }}\n   className=\"mt-1 flex min-h-11 w-full items-center justify-between gap-3 rounded-xl border border-gray-300 p-3 text-left text-sm\" style={colours}>\n   <span>{selected?.title || automatic}</span><span aria-hidden=\"true\">▾</span>\n  </button>\n  <dialog ref={dialog} aria-labelledby={titleId} onCancel={e => { e.preventDefault(); close(); }} onClose={close}\n   onClick={e => { if (e.target === e.currentTarget) { const rect = e.currentTarget.getBoundingClientRect(); if (e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom) close(); } }}\n   className=\"af-topic-picker\" style={colours}>\n   <div className=\"flex items-center justify-between gap-3 border-b border-gray-200 p-3\">\n    <h2 id={titleId} className=\"text-base font-semibold\" style={{color:'#111827'}}>{label}</h2>\n    <button type=\"button\" onClick={close} aria-label=\"Close topic picker\" className=\"min-h-11 rounded-lg border border-gray-300 px-3\" style={colours}>✕</button>\n   </div>\n   <div className=\"p-3\"><label className=\"sr-only\" htmlFor={`${titleId}-search`}>Search topics</label>\n    <input ref={search} id={`${titleId}-search`} type=\"search\" value={query} onChange={e => setQuery(e.target.value)} placeholder=\"Search topics or subjects…\" className=\"min-h-11 w-full rounded-lg border border-gray-300 px-3 text-base font-normal\" style={colours}/>\n    <p role=\"status\" className=\"mt-2 text-xs font-normal\" style={{color:'#475569'}}>{filtered.length} topics</p>\n   </div>\n   <div className=\"af-topic-picker-list\">\n    <button type=\"button\" onClick={() => choose('')} className=\"af-topic-choice\" style={colours}>{automatic}{!value && ' ✓'}</button>\n    {['Physics','Chemistry','Biology','Mathematics','Geophysics'].map(subject => {\n     const group = filtered.filter(t => t.subject === subject); if (!group.length) return null;\n     return <section key={subject} aria-label={subject}><h3 style={{color:'#3730a3',background:'#eef2ff',padding:'.6rem .75rem',fontSize:'.8rem'}}>{subject}</h3>\n      {group.map(t => <button key={t.id} type=\"button\" className=\"af-topic-choice\" style={colours} onClick={() => choose(t.id)} aria-pressed={value===t.id}>{t.title}{value === t.id && ' ✓'}</button>)}\n     </section>;\n    })}\n    {!filtered.length && <p className=\"p-4 text-sm font-normal\" style={{color:'#475569'}}>No topics match this search.</p>}\n   </div>\n  </dialog>\n </div>;\n}\n", "src/app/explore/page.tsx": "import { AppHeader } from '@/components/layout/AppHeader';\nimport { PromptBar } from '@/components/ai/PromptBar';\nimport { topics } from '@/lib/explorer/catalog';\nexport const metadata={title:'Topic explorer | A-Factor STEM Studio'};\nexport default function ExplorePage(){return <div style={{background:'#f1f5f9',minHeight:'100vh',color:'#111827',colorScheme:'light'}}><AppHeader/><main className=\"af-explorer mx-auto min-w-0 max-w-6xl px-3 py-6 sm:px-6 sm:py-10\"><p className=\"text-xs font-semibold uppercase tracking-widest text-indigo-700\">A-Factor STEM Studio</p><h1 className=\"mt-2 text-3xl font-semibold\">Explore all {topics.length} topics</h1><p className=\"mb-7 mt-3 max-w-2xl text-sm leading-7 text-gray-700\">Physics, Chemistry, Biology, Mathematics and Geophysics. Select an existing activity, prepare supported controls, and read a topic-specific explanation without a paid AI API.</p><PromptBar/></main></div>;}\n", "checks/classroom-controls.cjs": "const fs=require('fs'),path=require('path'),vm=require('vm'),ts=require('typescript'),assert=require('assert'),React=require('react'),{renderToStaticMarkup}=require('react-dom/server');\nlet initial=[];const cache=new Map();\nfunction load(file){file=path.resolve(file);if(file.endsWith('.json'))return JSON.parse(fs.readFileSync(file,'utf8'));if(cache.has(file))return cache.get(file).exports;\n const module={exports:{}};cache.set(file,module);\n const requireFile=id=>{if(id==='react'){let i=0;return {...React,useState:v=>[initial[i++]??v,()=>{}],useRef:v=>({current:v}),useEffect:()=>{},useCallback:fn=>fn,useId:()=> 'topic-test'};}if(id.startsWith('@/')){const base='src/'+id.slice(2);return load(fs.existsSync(base+'.ts')?base+'.ts':base+'.tsx');}if(id.endsWith('.css'))return {};if(id.startsWith('.')){let p=path.resolve(path.dirname(file),id);if(!path.extname(p))p+='.ts';return load(p);}return require(id);};\n const code=ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText;\n vm.runInNewContext(code,{module,exports:module.exports,require:requireFile,console});return module.exports;\n}\nconst catalog=JSON.parse(fs.readFileSync('src/lib/explorer/topics-data.json','utf8'));\nfor(const topic of catalog){const s=fs.readFileSync('src/app'+topic.route+'/page.tsx','utf8');assert(s.includes('SimulationStage')||s.includes('GeophysicsFrame')||s.includes('SkeletalActivity'),'fullscreen missing at '+topic.route);}\nfunction nodes(tree){let out=[];function visit(n){if(!React.isValidElement(n))return;out.push(n);React.Children.forEach(n.props.children,visit);}visit(tree);return out;}\ninitial=[false,''];const picker=load('src/components/explorer/TopicPicker.tsx');let chosen;\nlet tree=picker.TopicPicker({value:'',label:'Topic',automatic:'Automatic',onChange:id=>chosen=id});let buttons=nodes(tree).filter(n=>n.type==='button'&&n.props.className==='af-topic-choice');assert.equal(buttons.length,catalog.length+1);for(const b of buttons){assert.equal(b.props.style.color,'#111827');assert.equal(b.props.style.backgroundColor,'#fff');}\nbuttons[1].props.onClick();assert.equal(chosen,catalog.filter(t=>t.subject==='Physics')[0].id);\ninitial=[false,'pendulum'];cache.delete(path.resolve('src/components/explorer/TopicPicker.tsx'));tree=load('src/components/explorer/TopicPicker.tsx').TopicPicker({value:'',label:'Topic',automatic:'Automatic',onChange:()=>{}});buttons=nodes(tree).filter(n=>n.type==='button'&&n.props.className==='af-topic-choice');assert(buttons.length>1&&buttons.length<catalog.length);assert(!nodes(tree).some(n=>n.type==='select'));\nconst canvas=React.createElement('div',{'data-stage-role':'canvas',key:'canvas'},'Canvas');const controls=React.createElement('div',{'data-stage-role':'parameters',key:'parameters'},'Parameters');\nfor(const expanded of [false,true]){initial=[expanded];cache.delete(path.resolve('src/components/simulation/SimulationStage.tsx'));const stage=load('src/components/simulation/SimulationStage.tsx').SimulationStage({children:[canvas,controls]});const list=nodes(stage);assert(list.find(n=>n.props.className==='af-stage-main').props.children[0].props.children==='Canvas');assert(list.find(n=>n.type==='aside').props.children[0].props.children==='Parameters');assert.equal(stage.props['data-expanded'],expanded);assert(renderToStaticMarkup(stage).includes('Simulation parameters'));}\nconsole.log(`PASS: all ${catalog.length} catalogue activities have fullscreen; picker lists/searches/selects topics with explicit contrast; scene/sidebar structure remains stable across expansion.`);\n", "checks/embed-layout.cjs": "const fs=require('fs'),ts=require('typescript'),assert=require('assert');\nlet count=0;\nfor(const d of fs.readdirSync('src/app/embed',{withFileTypes:true}).filter(e=>e.isDirectory())){\n const file=`src/app/embed/${d.name}/page.tsx`,source=fs.readFileSync(file,'utf8'),ast=ts.createSourceFile(file,source,99,true,4);\n if(d.name==='skeletal-system'){assert(source.includes('SkeletalActivity embed'));count++;continue;}\n assert(source.includes('af-embed-stage'),`missing common embed class: ${d.name}`);\n assert(source.includes('data-stage-role=\"canvas\"'),`missing canvas slot: ${d.name}`);\n let canvasCount=0;\n function tag(n){return (ts.isJsxElement(n)?n.openingElement:ts.isJsxSelfClosingElement(n)?n:null)?.tagName.getText(ast)||'';}\n function role(n){return ts.isJsxElement(n)?n.openingElement.attributes.properties.find(p=>p.name?.text==='data-stage-role')?.initializer?.text:undefined;}\n function walk(n){\n  if(ts.isJsxSelfClosingElement(n)&&/Canvas$/.test(tag(n))){canvasCount++;for(const p of n.attributes.properties){if(p.name?.text==='width')assert(!(ts.isJsxExpression(p.initializer)&&ts.isNumericLiteral(p.initializer.expression)),`fixed width ${d.name}`);}}\n  if(ts.isJsxSelfClosingElement(n)&&tag(n)==='SimulationControls'){let p=n.parent;while(p&&!role(p))p=p.parent;assert.equal(role(p),'playback',`playback inside wrong panel ${d.name}`);}\n  if(ts.isJsxSelfClosingElement(n)&&/Graph$/.test(tag(n))){let p=n.parent;while(p&&!role(p))p=p.parent;assert.notEqual(role(p),'parameters',`graph inside header ${d.name}`);}\n  ts.forEachChild(n,walk);\n }\n walk(ast);assert(canvasCount>0,`no canvas ${d.name}`);\n assert(source.includes('useResponsiveCanvasSize')||source.includes('AtomicModelsCanvas')||source.includes('MosfetCanvas'),`no sizing strategy ${d.name}`);\n count++;\n}\nassert.equal(count,36);\nconsole.log(`PASS: ${count} embeds have shared stages, responsive canvases, separate playback and no auxiliary graphs in parameter headers.`);\n", "src/lib/biology/languages.ts": "import type { Language } from '@/lib/explorer/catalog';\nexport const biologyText:Record<Language,{title:string;instruction:string;overview:string;language:string}> = {\n en:{title:'Human skeletal system',instruction:'Select a bone on the diagram or use the bone list. Compare its division, location and function.',overview:'The skeleton supports the body, protects organs and provides levers for movement. A typical adult has 206 bones: 80 axial and 126 appendicular. The diagram groups bones and is not a count of every individual bone.',language:'Language'},\n yo:{title:'Ètò egungun ènìyàn',instruction:'Yan egungun kan nínú àwòrán tàbí àkójọ. Ṣe àfiwé ibi tí ó wà àti iṣẹ́ rẹ̀.',overview:'Egungun ń gbé ara dúró, ó ń dáàbò bo àwọn ẹ̀yà ara, ó sì ń ran ìṣípò lọ́wọ́. Àgbàlagbà sábà ní egungun 206: 80 ní axial àti 126 ní appendicular. Àwòrán yìí kó àwọn egungun jọ sí ẹgbẹ́.',language:'Èdè'},\n ha:{title:'Tsarin ƙasusuwan ɗan Adam',instruction:'Zaɓi ƙashi a zane ko daga jerin sunaye. Kwatanta inda yake da aikinsa.',overview:'Ƙasusuwan jiki suna tallafa wa jiki, suna kare gaɓobin ciki kuma suna taimaka wa motsi. Yawanci babban mutum yana da ƙasusuwa 206: 80 na axial da 126 na appendicular. Wannan zane ya haɗa wasu ƙasusuwa cikin rukuni.',language:'Harshe'},\n ig:{title:'Usoro ọkpụkpụ mmadụ',instruction:'Họrọ ọkpụkpụ n’eserese ma ọ bụ n’ndepụta aha. Tulee ebe ọ dị na ọrụ ya.',overview:'Ọkpụkpụ na-akwado ahụ, na-echebe akụkụ ahụ dị n’ime ma na-enyere mmegharị aka. Okenye na-enwekarị ọkpụkpụ 206: 80 axial na 126 appendicular. Eserese a chịkọtara ụfọdụ ọkpụkpụ n’otu.',language:'Asụsụ'},\n};\n", "src/lib/biology/skeleton.ts": "export type Division = 'axial' | 'appendicular';\nexport type Bone = { id:string; name:string; count:number; division:Division; location:string; function:string; anchor:[number,number]; label:[number,number]; view?:'front'|'back' };\n// Counts are grouped, not one SVG shape per bone. Typical adult convention.\nexport const BONES: Bone[] = [\n {id:'cranium',name:'Cranium',count:8,division:'axial',location:'Upper skull.',function:'Forms the protective case around the brain.',anchor:[280,66],label:[393,41]},\n {id:'face',name:'Facial bones (excluding mandible)',count:13,division:'axial',location:'Face; the mandible is listed separately.',function:'Form the framework of the face.',anchor:[295,101],label:[393,70],view:'front'},\n {id:'mandible',name:'Mandible',count:1,division:'axial',location:'Lower jaw.',function:'Supports the lower teeth and moves at the jaw joint.',anchor:[280,125],label:[393,99],view:'front'},\n {id:'ossicles',name:'Auditory ossicles',count:6,division:'axial',location:'Three tiny bones in each middle ear; shown as a callout.',function:'Transmit vibrations through the middle ear.',anchor:[318,92],label:[393,128]},\n {id:'hyoid',name:'Hyoid',count:1,division:'axial',location:'Neck, below the mandible; shown schematically.',function:'Supports the tongue and provides muscle attachments.',anchor:[280,147],label:[393,157],view:'front'},\n {id:'vertebrae',name:'Vertebral column',count:26,division:'axial',location:'Backbone, including the adult sacrum and coccyx.',function:'Supports the trunk and surrounds the spinal cord.',anchor:[280,309],label:[393,302]},\n {id:'ribs',name:'Ribs',count:24,division:'axial',location:'Twelve pairs around the chest.',function:'Help protect the heart and lungs.',anchor:[329,240],label:[393,244]},\n {id:'sternum',name:'Sternum',count:1,division:'axial',location:'Midline at the front of the chest.',function:'Forms the anterior centre of the rib cage.',anchor:[280,213],label:[393,215],view:'front'},\n {id:'clavicles',name:'Clavicles',count:2,division:'appendicular',location:'Collarbones at the front of the shoulder girdle.',function:'Help connect the shoulder girdle to the trunk.',anchor:[237,171],label:[36,157],view:'front'},\n {id:'scapulae',name:'Scapulae',count:2,division:'appendicular',location:'Shoulder blades at the back of the chest.',function:'Provide shoulder sockets and muscle attachments.',anchor:[229,204],label:[36,186],view:'back'},\n {id:'humeri',name:'Humeri',count:2,division:'appendicular',location:'One humerus in each upper arm.',function:'Connect the shoulder to the elbow.',anchor:[192,254],label:[36,244]},\n {id:'radii',name:'Radii',count:2,division:'appendicular',location:'Thumb side of each forearm in anatomical position.',function:'Work with the ulnae during forearm rotation.',anchor:[157,359],label:[36,331]},\n {id:'ulnae',name:'Ulnae',count:2,division:'appendicular',location:'Little-finger side of each forearm.',function:'Form a major part of the elbow joint.',anchor:[172,348],label:[36,302]},\n {id:'carpals',name:'Carpals',count:16,division:'appendicular',location:'Eight bones in each wrist.',function:'Form the wrist framework.',anchor:[142,430],label:[36,389]},\n {id:'metacarpals',name:'Metacarpals',count:10,division:'appendicular',location:'Five bones in each palm.',function:'Connect the wrist to the fingers.',anchor:[136,452],label:[36,418]},\n {id:'hand-phalanges',name:'Hand phalanges',count:28,division:'appendicular',location:'Fourteen bones in each hand; two in the thumb, three in each finger.',function:'Form the finger skeleton.',anchor:[124,485],label:[36,447]},\n {id:'hip-bones',name:'Hip bones',count:2,division:'appendicular',location:'Pelvic girdle; the sacrum belongs to the axial skeleton.',function:'Connect the lower limbs to the axial skeleton.',anchor:[245,367],label:[393,360]},\n {id:'femora',name:'Femora',count:2,division:'appendicular',location:'One femur in each thigh.',function:'Transmit load between the hip and knee.',anchor:[241,456],label:[393,447]},\n {id:'patellae',name:'Patellae',count:2,division:'appendicular',location:'Kneecaps at the front of the knee.',function:'Help the knee-extensor mechanism.',anchor:[238,530],label:[393,505],view:'front'},\n {id:'tibiae',name:'Tibiae',count:2,division:'appendicular',location:'Medial, larger bones of the lower legs.',function:'Carry most of the load through the lower leg.',anchor:[245,606],label:[393,563]},\n {id:'fibulae',name:'Fibulae',count:2,division:'appendicular',location:'Slender lateral bones of the lower legs.',function:'Provide muscle attachments and contribute to ankle stability.',anchor:[224,608],label:[36,563]},\n {id:'tarsals',name:'Tarsals',count:14,division:'appendicular',location:'Seven bones in each ankle/hindfoot region.',function:'Form the hindfoot framework.',anchor:[239,699],label:[393,650]},\n {id:'metatarsals',name:'Metatarsals',count:10,division:'appendicular',location:'Five bones in each mid/forefoot.',function:'Connect the tarsals to the toe bones.',anchor:[225,721],label:[393,679]},\n {id:'foot-phalanges',name:'Foot phalanges',count:28,division:'appendicular',location:'Fourteen bones in each foot.',function:'Form the toe skeleton.',anchor:[212,744],label:[393,708]},\n];\nexport const SOURCES = [\n ['Skeletal divisions','https://openstax.org/books/anatomy-and-physiology-2e/pages/7-1-divisions-of-the-skeletal-system'],\n ['Upper limb','https://openstax.org/books/anatomy-and-physiology-2e/pages/8-2-bones-of-the-upper-limb'],\n ['Lower limb','https://openstax.org/books/anatomy-and-physiology-2e/pages/8-4-bones-of-the-lower-limb'],\n ['Thoracic cage','https://openstax.org/books/anatomy-and-physiology-2e/pages/7-4-the-thoracic-cage'],\n];\nexport const EXERCISES = [\n {q:'Classify the skull, ribs, humerus and femur as axial or appendicular.',a:'Skull and ribs: axial. Humerus and femur: appendicular.'},\n {q:'A learner counts 80 axial bones and 126 appendicular bones. Find the total and the difference.',a:'Total = 80 + 126 = 206. Difference = 126 − 80 = 46 bones.'},\n {q:'Why does selecting “Ribs” highlight several shapes?',a:'The selectable region represents 12 pairs, or 24 individual bones. This diagram groups bones for teaching.'},\n {q:'Explain why a hip bone and the sacrum belong to different divisions, although both are in the pelvis.',a:'The hip bones belong to the appendicular pelvic girdle. The sacrum is part of the axial vertebral column.'},\n {q:'Locate the radius and ulna. Which lies on the thumb side in anatomical position?',a:'Both are forearm bones. The radius is on the thumb side; the ulna is on the little-finger side.'},\n {q:'How many phalanges are in one hand? How are they distributed?',a:'14: two in the thumb and three in each of the four fingers.'},\n {q:'Compare the tibia and fibula in position and role.',a:'The tibia is medial and carries most lower-leg load. The fibula is lateral and contributes to attachments and ankle stability.'},\n {q:'Assignment: choose a familiar movement. Name two bones involved and explain why bones alone cannot produce it.',a:'Example: elbow bending involves the humerus, radius and ulna. Muscles generate force; bones act as levers at joints.'},\n];\nexport function challengeBone(index:number) { return BONES[((Math.trunc(index)*7+5)%BONES.length+BONES.length)%BONES.length]; }\n", "src/components/biology/biology.css": ".bio-page { background:#f1f5f9; color:#0f172a; min-height:100vh; }\n.bio-embed { padding:.5rem; }\n.bio-card { padding:1.1rem; border:1px solid #cbd5e1; border-radius:1rem; background:white; }\n.bio-button { min-height:44px; border:1px solid #cbd5e1; border-radius:.6rem; padding:.5rem .75rem; background:white; color:#134e4a; font-size:.85rem; cursor:pointer; }\n.bio-button:disabled { opacity:.55; cursor:default; }\n.bio-button[aria-pressed=\"true\"] { background:#ccfbf1; border-color:#0f766e; }\n.bio-page :is(button,select,input,summary,a):focus-visible { outline:3px solid #f59e0b; outline-offset:3px; }\n.bio-scene { display:grid; grid-template-columns:minmax(0,1fr) 280px; gap:1rem; padding:.75rem; border:1px solid #cbd5e1; border-radius:1rem; background:white; }\n.bio-figure { height:min(75vh,760px); min-height:350px; overflow:auto; background:#f8fafc; border-radius:.75rem; }\n.bio-zoom { min-height:0; min-width:0; text-align:center; }\n.bio-skeleton { display:inline-block; width:auto; height:100%; max-width:none; vertical-align:top; }\n.bio-info { padding:.75rem; overflow:auto; }\n.bio-controls { display:flex; flex-wrap:wrap; gap:.75rem; padding:.75rem; border-radius:.75rem; background:white; border:1px solid #cbd5e1; }\n.bio-controls label { display:flex; flex-direction:column; gap:.4rem; color:#134e4a; font-size:.75rem; }\n.bio-controls select { min-height:44px; max-width:220px; border:1px solid #cbd5e1; border-radius:.5rem; background:white; color:#0f172a; padding:.4rem; font-size:.85rem; }\n.bio-controls input[type=\"checkbox\"] { width:24px; height:24px; }\n.bio-controls input[type=\"range\"] { width:160px; min-height:36px; accent-color:#0f766e; }\n.bio-bone:focus-visible { outline:none; }\n.bio-bone:focus-visible > g:first-of-type { stroke:#b45309; stroke-width:4; }\n.af-biology-stage[data-expanded=\"true\"] .bio-scene { display:grid; grid-template-columns:minmax(0,1fr) clamp(210px,26vw,300px); min-height:0; overflow:hidden; padding:.25rem; gap:.5rem; }\n.af-biology-stage[data-expanded=\"true\"] .bio-figure { height:100%; min-height:0; }\n.af-biology-stage[data-expanded=\"true\"] .bio-info { min-height:0; }\n@media(max-width:640px) and (orientation:portrait) {\n .bio-scene { grid-template-columns:minmax(0,1fr); }\n .bio-figure { height:65vh; }\n .af-biology-stage[data-expanded=\"true\"] .bio-scene { grid-template-columns:minmax(0,1fr); grid-template-rows:minmax(0,1fr) minmax(90px,25%); }\n .bio-controls select { font-size:16px; }\n}\n.bio-page select option { color:#0f172a; background:#fff; }\n", "src/components/biology/SkeletonDiagram.tsx": "'use client';\nimport { Fragment, type ReactNode, useId } from 'react';\nimport { BONES, type Bone } from '@/lib/biology/skeleton';\ntype Props = { selected:string|null; division:string; view:'front'|'back'; labels:boolean; interactive:boolean; onSelect:(id:string)=>void };\nconst line = (x1:number,y1:number,x2:number,y2:number,w=9) => <path d={`M${x1} ${y1}L${x2} ${y2}`} fill=\"none\" strokeWidth={w} strokeLinecap=\"round\"/>;\nfunction pair(node:ReactNode) { return <>{node}<g transform=\"translate(560 0) scale(-1 1)\">{node}</g></>; }\nfunction shape(id:string,back:boolean):ReactNode {\n switch(id) {\n  case 'cranium':return <path d=\"M242 91 C230 38 246 28 280 28 C314 28 330 49 318 91 L305 104 L255 104Z\"/>;\n  case 'face':return <><path d=\"M248 93L256 119L269 124L291 124L304 119L312 93L298 86L280 95L262 86Z\"/><ellipse cx=\"263\" cy=\"100\" rx=\"8\" ry=\"6\" fill=\"#1e293b\"/><ellipse cx=\"297\" cy=\"100\" rx=\"8\" ry=\"6\" fill=\"#1e293b\"/><path d=\"M280 105L274 116L286 116Z\" fill=\"#1e293b\"/></>;\n  case 'mandible':return <path d=\"M250 110L256 134Q280 149 304 134L310 110L301 112L296 128Q280 135 264 128L259 112Z\"/>;\n  case 'ossicles':return pair(<g><circle cx=\"239\" cy=\"92\" r=\"4\"/><circle cx=\"233\" cy=\"94\" r=\"3\"/><circle cx=\"229\" cy=\"97\" r=\"2\"/></g>);\n  case 'hyoid':return <path d=\"M269 143Q280 155 291 143L292 150Q280 162 268 150Z\"/>;\n  case 'vertebrae':return <>{Array.from({length:24},(_,i)=><rect key={i} x={back?272:275} y={145+i*8.5} width={back?16:10} height=\"7\" rx=\"2\"/>)}<path d=\"M265 352L295 352L288 383L280 399L272 383Z\"/></>;\n  case 'ribs':return <>{Array.from({length:12},(_,i)=>{const y=181+i*9,w=i<8?48+i*2:66-(i-7)*10;return <Fragment key={i}>{pair(<path d={`M276 ${y} Q${280-w-24} ${y-12} ${280-w} ${y+10} Q${280-w+5} ${y+25} 274 ${y+17}`} strokeWidth=\"4\" fill=\"none\"/>)}</Fragment>;})}</>;\n  case 'sternum':return <path d=\"M270 175L290 175L287 193L285 243L280 255L275 243L273 193Z\"/>;\n  case 'clavicles':return pair(<path d=\"M275 170Q250 158 231 173Q221 180 208 177\" fill=\"none\" strokeWidth=\"8\" strokeLinecap=\"round\"/>);\n  case 'scapulae':return pair(<path d=\"M218 181L257 191L241 241L213 211Z\"/>);\n  case 'humeri':return pair(<>{line(207,197,177,303,13)}<circle cx=\"207\" cy=\"192\" r=\"12\"/><ellipse cx=\"177\" cy=\"306\" rx=\"12\" ry=\"8\"/></>);\n  case 'radii':return pair(<>{line(165,321,139,420,7)}<ellipse cx=\"139\" cy=\"419\" rx=\"7\" ry=\"5\"/></>);\n  case 'ulnae':return pair(<>{line(179,316,151,419,7)}<path d=\"M173 306L184 307L180 321L171 320Z\"/></>);\n  case 'carpals':return pair(<>{Array.from({length:8},(_,i)=><circle key={i} cx={134+(i%4)*5} cy={429+Math.floor(i/4)*6} r=\"3\"/>)}</>);\n  case 'metacarpals':return pair(<>{Array.from({length:5},(_,i)=>line(134+i*4,440,122+i*6,460,3))}</>);\n  case 'hand-phalanges':return pair(<>{Array.from({length:5},(_,finger)=>Array.from({length:finger===0?2:3},(_,j)=>line(122+finger*6-j*1.5,464+j*7,121+finger*6-j*1.5,469+j*7,3)))}</>);\n  case 'hip-bones':return pair(<path d=\"M269 342Q238 331 218 349L214 373L227 395L257 405L270 385L251 378L260 359Z M239 381L251 387L240 395L231 388Z\" fillRule=\"evenodd\"/>);\n  case 'femora':return pair(<><circle cx=\"255\" cy=\"396\" r=\"11\"/>{line(250,405,238,516,14)}<path d=\"M236 406L239 395L248 402Z\"/><ellipse cx=\"238\" cy=\"520\" rx=\"13\" ry=\"9\"/></>);\n  case 'patellae':return pair(<path d=\"M230 528Q238 519 246 528L244 540L238 546L232 540Z\"/>);\n  case 'tibiae':return pair(<>{line(241,550,239,684,11)}<path d=\"M230 547L251 547L247 564L236 564Z\"/></>);\n  case 'fibulae':return pair(<>{line(224,551,225,684,5)}<circle cx=\"224\" cy=\"550\" r=\"5\"/></>);\n  case 'tarsals':return pair(<>{Array.from({length:7},(_,i)=><ellipse key={i} cx={230+(i%3)*6} cy={694+Math.floor(i/3)*6} rx=\"4\" ry=\"3\"/>)}</>);\n  case 'metatarsals':return pair(<>{Array.from({length:5},(_,i)=>line(226+i*4,711,209+i*7,732,4))}</>);\n  case 'foot-phalanges':return pair(<>{Array.from({length:5},(_,toe)=>Array.from({length:toe===4?2:3},(_,j)=>line(209+toe*7-j*2,735+j*4,206+toe*7-j*2,737+j*4,3)))}</>);\n  default:return null;\n }\n}\nfunction shortName(b:Bone) { return b.id==='face'?'Facial bones':b.id==='vertebrae'?'Vertebral column':b.name; }\nexport function SkeletonDiagram({selected,division,view,labels,interactive,onSelect}:Props) {\n const title=useId(),desc=useId();\n return <svg viewBox=\"0 0 560 780\" role=\"group\" aria-labelledby={`${title} ${desc}`} className=\"bio-skeleton\">\n  <title id={title}>Human skeleton — {view} view</title><desc id={desc}>Simplified adult skeleton. Select bones with touch, mouse, Enter or Space. A separate bone list provides the same controls. Tiny ear bones and the hyoid are schematic callouts.</desc>\n  <rect width=\"560\" height=\"780\" rx=\"18\" fill=\"#f8fafc\"/>\n  <text x=\"280\" y=\"19\" textAnchor=\"middle\" fontSize=\"12\" fill=\"#475569\">{view==='front'?'Anterior (front)':'Posterior (back)'} · grouped teaching diagram</text>\n  {BONES.filter(b=>!b.view||b.view===view).sort((a,b)=>a.id==='vertebrae'?-1:b.id==='vertebrae'?1:0).map(b=>{\n   const active=division==='all'||b.division===division,chosen=selected===b.id;\n   return <g key={b.id} className=\"bio-bone\" role={interactive?'button':undefined} tabIndex={interactive&&active?0:undefined} aria-label={`${b.name}, ${b.count} bones, ${b.division}`} aria-pressed={interactive?chosen:undefined}\n    onClick={()=>{if(interactive&&active)onSelect(b.id);}} onKeyDown={e=>{if(interactive&&active&&(e.key==='Enter'||e.key===' ')){e.preventDefault();onSelect(b.id);}}}\n    style={{opacity:active?1:.12,cursor:interactive&&active?'pointer':'default'}}>\n    <title>{b.name}</title><g fill={chosen?'#fde68a':b.division==='axial'?'#dbeafe':'#ccfbf1'} stroke={chosen?'#b45309':b.division==='axial'?'#2563eb':'#0f766e'} strokeWidth={chosen?3:1.8}>{shape(b.id,view==='back')}</g>\n    {labels&&active&&<g pointerEvents=\"none\"><path d={`M${b.anchor[0]} ${b.anchor[1]}L${b.label[0]<280?152:389} ${b.label[1]-4}`} stroke=\"#94a3b8\" strokeWidth=\".8\" fill=\"none\"/><text x={b.label[0]} y={b.label[1]} fontSize=\"11\" fontWeight={chosen?700:500} fill=\"#0f172a\">{shortName(b)}</text></g>}\n   </g>;\n  })}\n </svg>;\n}\n", "src/components/biology/SkeletalActivity.tsx": "'use client';\nimport { useEffect, useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { ReadAloud } from '@/components/accessibility/ReadAloud';\nimport { isLanguage, type Language } from '@/lib/explorer/catalog';\nimport { languageNames } from '@/lib/explorer/locales';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\nimport { BONES, EXERCISES, SOURCES, challengeBone, type Bone } from '@/lib/biology/skeleton';\nimport { biologyText } from '@/lib/biology/languages';\nimport { SkeletonDiagram } from './SkeletonDiagram';\nimport './biology.css';\ntype Task='explore'|'identify'|'classify';\nexport function SkeletalActivity({embed=false}:{embed?:boolean}) {\n const [view,setView]=useState<'front'|'back'>('front'),[division,setDivision]=useState('all'),[labels,setLabels]=useState(true),[selected,setSelected]=useState(0);\n const [task,setTask]=useState<Task>('explore'),[language,setLanguage]=useState<Language>('en'),[controls,setControls]=useState(true),[zoom,setZoom]=useState(100);\n const [question,setQuestion]=useState(0),[answered,setAnswered]=useState(false),[revealed,setRevealed]=useState(false),[feedback,setFeedback]=useState(''),[score,setScore]=useState({correct:0,total:0});\n const [tab,setTab]=useState<'student'|'teacher'>('student');\n const bone=BONES[selected],target=challengeBone(question),text=biologyText[language];\n function selectBone(id:string) {\n  const i=BONES.findIndex(b=>b.id===id);if(i<0)return;\n  if(task==='identify'){answer(id===target.id);return;}\n  setSelected(i);const b=BONES[i];if(b.view)setView(b.view);\n }\n function answer(correct:boolean) {\n  if(answered)return;setAnswered(true);setScore(s=>({correct:s.correct+(correct?1:0),total:s.total+1}));\n  setFeedback(correct?'Correct. Explain the location or function to a partner.':'Not quite. Use Reveal to review the answer, then try the next challenge.');\n }\n function startTask(value:Task){setTask(value);setQuestion(0);setAnswered(false);setRevealed(false);setFeedback('');if(value!=='explore'){setDivision('all');}if(value!=='explore'){const t=challengeBone(0);setView(t.view||'front');}}\n function next(){const t=challengeBone(question+1);setQuestion(q=>q+1);setAnswered(false);setRevealed(false);setFeedback('');setView(t.view||'front');}\n function reveal(){setRevealed(true);if(!answered){setAnswered(true);setScore(s=>({...s,total:s.total+1}));}setFeedback(`Answer: ${target.name} — ${target.division}. ${target.function}`);}\n function reset(){setView('front');setDivision('all');setLabels(true);setSelected(0);setZoom(100);setTask('explore');setQuestion(0);setAnswered(false);setRevealed(false);setFeedback('');setScore({correct:0,total:0});}\n useEffect(()=>{\n  const q=new URLSearchParams(window.location.search);\n  const v=q.get('view');if(v==='front'||v==='back')setView(v);\n  const d=q.get('division');if(d&&['all','axial','appendicular'].includes(d))setDivision(d);\n  if(q.get('labels')==='0')setLabels(false);\n  const index=Number(q.get('bone'));if(q.has('bone')&&Number.isInteger(index)&&index>=0&&index<BONES.length){setSelected(index);if(BONES[index].view)setView(BONES[index].view!);}\n  const t=q.get('task');if(t==='identify'||t==='classify')startTask(t);\n  if(embed&&q.get('controls')==='0'){setControls(false);setTask('explore');}\n  try{const saved=q.get('afLang')||q.get('lang')||localStorage.getItem('afactor-simulation-language-v1');if(isLanguage(saved))setLanguage(saved);}catch{}\n },[embed]);\n useTopicPreset('biology-skeletal-system',{boneIndex:v=>{const n=Math.max(0,Math.min(BONES.length-1,Math.trunc(v)));setSelected(n);}}, {\n  view:v=>setView(v as 'front'|'back'),division:setDivision,labels:v=>setLabels(v==='on'),activity:v=>startTask(v as Task),\n });\n function changeLanguage(value:Language){setLanguage(value);try{localStorage.setItem('afactor-simulation-language-v1',value);}catch{}}\n const challenge=task!=='explore',shown:Bone=challenge?target:bone;\n const heading=task==='identify'?`Find and select: ${target.name}`:task==='classify'?`Classify: ${target.name}`:bone.name;\n const showAnswer=!challenge||revealed||task==='classify';\n return <div className=\"bio-page\" style={{colorScheme:'light'}}>\n  {!embed&&<AppHeader/>}\n  <main className={embed?'bio-embed':'mx-auto max-w-7xl px-3 py-6 sm:px-6'}>\n   {!embed&&<><Link href=\"/biology\" className=\"text-sm text-teal-800 underline\">← Biology</Link><h1 className=\"mt-2 text-2xl font-semibold\">{text.title}</h1><p className=\"my-3 max-w-3xl text-sm leading-7\">{text.instruction}</p></>}\n   <SimulationStage className={`af-biology-stage ${embed?'af-embed-stage':''} space-y-3`}>\n    <div data-stage-role=\"canvas\" className=\"bio-scene\">\n     <div className=\"bio-figure\"><div className=\"bio-zoom\" style={{height:`${zoom}%`}}><SkeletonDiagram selected={challenge?(revealed||task==='classify'?target.id:null):bone.id} division={challenge?'all':division} view={view} labels={challenge?revealed:labels} interactive={controls&&(task==='explore'||(task==='identify'&&!answered))} onSelect={selectBone}/></div></div>\n     <aside className=\"bio-info\" lang=\"en\">\n      <p className=\"text-xs font-semibold uppercase tracking-wider text-teal-700\">{challenge?'Student challenge':'Selected bone or group'}</p>\n      <h2 className=\"my-2 text-lg font-semibold\">{heading}</h2>\n      {showAnswer&&<><p className=\"my-2 text-sm\"><strong>{shown.count}</strong> {shown.count===1?'bone':'bones'} · <strong>{task==='classify'&&!revealed?'Choose a division below':shown.division}</strong></p>\n       <p className=\"text-sm leading-6\">{shown.location}</p><p className=\"mt-2 text-sm leading-6\">{shown.function}</p>\n       {!challenge&&<ReadAloud text={`${bone.name}. ${bone.location} ${bone.function}`} language=\"en\"/>}</>}\n      {controls&&task==='classify'&&<div className=\"mt-3 flex flex-wrap gap-2\">{(['axial','appendicular'] as const).map(d=><button className=\"bio-button\" key={d} disabled={answered} onClick={()=>answer(d===target.division)}>{d}</button>)}</div>}\n      {task==='identify'&&!answered&&<p className=\"text-sm leading-6\">Labels are hidden. Tap the named group on the diagram, or use the accessible bone list.</p>}\n      {challenge&&<><p className=\"mt-3 text-sm font-medium\">Score: {score.correct}/{score.total} first attempts</p><p role=\"status\" className=\"mt-2 text-sm leading-6\">{feedback}</p></>}\n      <p className=\"mt-4 text-xs leading-5 text-gray-600\">Typical adult count: 206 (80 axial + 126 appendicular). This schematic groups bones; it does not show all 206 separately. Some internal bones are callouts.</p>\n     </aside>\n    </div>\n    {controls&&<div data-stage-role=\"parameters\" className=\"bio-controls\">\n     <label>Activity<select value={task} onChange={e=>startTask(e.target.value as Task)}><option value=\"explore\">Explore bones</option><option value=\"identify\">Identify a bone</option><option value=\"classify\">Axial or appendicular?</option></select></label>\n     <label>Bone / group<select value={task==='identify'?'':String(selected)} disabled={task==='classify'||(task==='identify'&&answered)} onChange={e=>{if(e.target.value)selectBone(BONES[Number(e.target.value)].id);}}>{task==='identify'&&<option value=\"\">Choose a bone…</option>}{BONES.map((b,i)=><option key={b.id} value={String(i)}>{b.name}</option>)}</select></label>\n     <label>View<select value={view} disabled={challenge} onChange={e=>setView(e.target.value as 'front'|'back')}><option value=\"front\">Front</option><option value=\"back\">Back</option></select></label>\n     <label>Division<select disabled={challenge} value={division} onChange={e=>setDivision(e.target.value)}><option value=\"all\">All bones</option><option value=\"axial\">Axial · 80 bones</option><option value=\"appendicular\">Appendicular · 126 bones</option></select></label>\n     <label>Labels<input type=\"checkbox\" checked={labels} disabled={challenge} onChange={e=>setLabels(e.target.checked)}/></label>\n     <label>{text.language}<select value={language} onChange={e=>changeLanguage(e.target.value as Language)}>{Object.entries(languageNames).map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label>\n     <label>Diagram zoom {zoom}%<input type=\"range\" min={75} max={160} step={5} value={zoom} onChange={e=>setZoom(Number(e.target.value))}/></label>\n    </div>}\n    {controls&&<div data-stage-role=\"playback\" className=\"flex flex-wrap gap-2\">\n     {challenge&&<><button className=\"bio-button\" onClick={reveal} disabled={revealed}>Reveal answer</button><button className=\"bio-button\" onClick={next}>Next challenge</button></>}\n     <button className=\"bio-button\" onClick={reset}>Reset activity</button>\n     {!embed&&<EmbedButton path=\"/embed/skeletal-system\" title=\"Human skeletal system — A-Factor STEM Studio\" width={900} height={720} params={{bone:selected,view,division,labels:labels?1:0,task,lang:language}}/>}\n    </div>}\n    <div data-stage-role=\"extra\" className=\"bio-card\"><h2 className=\"font-semibold\">Accessible bone list</h2><p className=\"my-2 text-xs text-gray-600\">The same selections as the diagram; useful on small screens and with a keyboard.</p><div className=\"grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4\">{BONES.filter(b=>challenge||division==='all'||b.division===division).map(b=><button key={b.id} className=\"bio-button text-left\" disabled={!controls||task==='classify'||(task==='identify'&&answered)} onClick={()=>selectBone(b.id)} aria-pressed={!challenge&&bone.id===b.id}>{b.name}</button>)}</div></div>\n   </SimulationStage>\n   <section className=\"bio-card mt-4\" lang={language}><h2 className=\"font-semibold\">{text.title}</h2><p className=\"my-2 text-sm leading-7\">{text.overview}</p><ReadAloud text={text.overview} language={language}/><p className=\"text-xs leading-6 text-gray-600\" lang=\"en\">Bone names, quizzes and detailed notes remain in English. Local-language overviews are draft teaching content for fluent-teacher review.</p></section>\n   {!embed&&<section className=\"mt-5\" lang=\"en\">\n    <div role=\"group\" aria-label=\"Learning sections\" className=\"mb-3 flex gap-2\"><button className=\"bio-button\" aria-pressed={tab==='student'} onClick={()=>setTab('student')}>Student activities</button><button className=\"bio-button\" aria-pressed={tab==='teacher'} onClick={()=>setTab('teacher')}>Teacher guide</button></div>\n    {tab==='teacher'?<TeacherGuide onChallenge={startTask}/>:<div className=\"bio-card\"><h2 className=\"text-lg font-semibold\">Explore → explain → practise</h2><ol className=\"my-3 list-decimal space-y-2 pl-5 text-sm leading-6\"><li>Select a bone and tell a partner where it is before revealing its function.</li><li>Compare front and back views. Find the sternum in front and the scapulae at the back.</li><li>Filter by division, then complete five identification and five classification challenges.</li><li>Explain one answer aloud. Your partner checks the diagram and the notes.</li></ol><h3 className=\"mt-4 font-semibold\">Worked example</h3><p className=\"my-2 text-sm leading-6\">Question: is the femur axial or appendicular? It lies in the thigh, which is part of a limb. Limb bones belong to the appendicular skeleton, so the femur is appendicular.</p><h3 className=\"mt-4 font-semibold\">Classwork and assignments</h3>{EXERCISES.map((e,i)=><details key={e.q} className=\"my-2 rounded-xl border border-gray-200 p-3\"><summary className=\"cursor-pointer text-sm font-medium\">{i+1}. {e.q}</summary><p className=\"mt-3 text-sm leading-6\">{e.a}</p></details>)}</div>}\n   </section>}\n   <footer className=\"my-5 text-xs leading-6 text-gray-600\" lang=\"en\"><p>Original schematic illustration; educational overview, not a diagnostic or surgical model. Challenges are local practice, not a secure assessment or a shared live session.</p><p>Reference reading: {SOURCES.map(([label,url])=><a key={url} className=\"mr-3 underline\" href={url} target=\"_blank\" rel=\"noreferrer\">OpenStax · {label}</a>)}</p>{embed&&<Link className=\"underline\" href=\"/biology/skeletal-system\" target=\"_blank\">Open the full lesson · A-Factor STEM Studio</Link>}</footer>\n  </main>\n </div>;\n}\nfunction TeacherGuide({onChallenge}:{onChallenge:(task:Task)=>void}) {\n return <div className=\"bio-card\"><h2 className=\"text-lg font-semibold\">Teacher guide · suggested 35-minute lesson</h2><h3 className=\"mt-3 font-semibold\">Learning objectives</h3><ul className=\"my-2 list-disc space-y-1 pl-5 text-sm leading-6\"><li>Locate major bones and distinguish axial from appendicular regions.</li><li>Relate a bone’s position to a supporting, protective or movement role.</li><li>Explain why a selected bone group is not always one individual bone.</li></ul><h3 className=\"mt-3 font-semibold\">Demonstration and interaction</h3><ol className=\"my-2 list-decimal space-y-2 pl-5 text-sm leading-6\"><li><strong>0–5 min:</strong> ask learners to name three bones. Collect predictions before showing labels.</li><li><strong>5–15 min:</strong> expand classroom view, compare front/back, and switch divisions. Ask “Why is the sacrum axial but a hip bone appendicular?”</li><li><strong>15–25 min:</strong> hide labels. Invite one learner to select a named bone; classmates justify or correct the choice. Rotate who answers and who explains.</li><li><strong>25–30 min:</strong> pairs alternate identification and classification challenges. Record first attempts on paper if needed.</li><li><strong>30–35 min:</strong> exit ticket: name one protective bone, one limb bone and their divisions.</li></ol><div className=\"my-3 flex flex-wrap gap-2\"><button className=\"bio-button\" onClick={()=>onChallenge('identify')}>Start identification challenge</button><button className=\"bio-button\" onClick={()=>onChallenge('classify')}>Start classification challenge</button></div><h3 className=\"mt-3 font-semibold\">Misconceptions and differentiation</h3><p className=\"my-2 text-sm leading-6\">Paired or grouped regions are not single bones. A bone does not contract like a muscle. Use the bone list and read-aloud controls for learners who need alternatives to the diagram. For extension, ask pupils to explain movement using bones, joints and muscles.</p><p className=\"text-xs leading-6 text-gray-600\">These activities support interaction around a shared screen. No learner accounts, microphone recording, remote classroom synchronization or student data collection are added.</p></div>;\n}\n", "src/app/biology/page.tsx": "import Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nexport const metadata={title:'Biology simulations | A-Factor STEM Studio'};\nexport default function BiologyHub(){return <div className=\"min-h-screen bg-gray-50 text-gray-900\"><AppHeader/><main className=\"mx-auto max-w-7xl px-4 py-8 sm:px-6\"><p className=\"text-sm font-semibold text-teal-700\">A-Factor STEM Studio · Biology</p><h1 className=\"mt-2 text-3xl font-semibold\">Explore living systems</h1><p className=\"my-4 max-w-2xl text-sm leading-7 text-gray-600\">Interactive models, classroom challenges, teacher guidance and student practice.</p><Link href=\"/biology/skeletal-system\" className=\"block max-w-md rounded-2xl border border-teal-200 bg-white p-6 shadow-sm hover:border-teal-600\"><span aria-hidden=\"true\" className=\"text-3xl\">🦴</span><h2 className=\"my-3 text-xl font-semibold\">Human skeletal system</h2><p className=\"text-sm leading-7 text-gray-600\">Explore the major bones, compare axial and appendicular divisions, and practise identification with your teacher or a partner.</p><p className=\"mt-4 font-medium text-teal-800\">Open activity →</p></Link></main></div>;}\n", "src/app/biology/skeletal-system/page.tsx": "import { SkeletalActivity } from '@/components/biology/SkeletalActivity';\nexport const metadata={title:'Human skeletal system | A-Factor STEM Studio'};\nexport default function SkeletalSystemPage(){return <SkeletalActivity/>;}\n", "src/app/embed/skeletal-system/page.tsx": "import { SkeletalActivity } from '@/components/biology/SkeletalActivity';\nexport default function SkeletalSystemEmbed(){return <SkeletalActivity embed/>;}\n", "checks/biology-skeleton.cjs": "const fs=require('fs'),path=require('path'),vm=require('vm'),ts=require('typescript'),assert=require('assert'),React=require('react');\nconst slots=[],cache=new Map();let cursor=0;\nconst stub=()=>null;\nconst hooks={...React,useState(initial){const i=cursor++;if(!(i in slots))slots[i]=typeof initial==='function'?initial():initial;return [slots[i],value=>{slots[i]=typeof value==='function'?value(slots[i]):value;}];},useEffect:()=>{},useId:()=> 'skeleton-test'};\nfunction load(file){file=path.resolve(file);if(file.endsWith('.json'))return JSON.parse(fs.readFileSync(file,'utf8'));if(cache.has(file))return cache.get(file).exports;const module={exports:{}};cache.set(file,module);\n function req(id){if(id==='react')return hooks;if(id==='react/jsx-runtime')return require(id);if(id==='next/link')return {__esModule:true,default:stub};\n if(id.includes('/use-topic-preset'))return {useTopicPreset:()=>{}};\n if(id.includes('/AppHeader'))return {AppHeader:stub};if(id.includes('/SimulationStage'))return {SimulationStage:stub};if(id.includes('/ReadAloud'))return {ReadAloud:stub};if(id.includes('/EmbedButton'))return {EmbedButton:stub};if(id.endsWith('.css'))return {};\n let target=id.startsWith('@/')?'src/'+id.slice(2):id.startsWith('.')?path.resolve(path.dirname(file),id):null;if(!target)return require(id);if(!path.extname(target))target+=fs.existsSync(target+'.ts')?'.ts':'.tsx';return load(target);}\n const code=ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText;\n vm.runInNewContext(code,{module,exports:module.exports,require:req,console,Math,URLSearchParams,cancelAnimationFrame:()=>{}});return module.exports;\n}\nconst data=load('src/lib/biology/skeleton.ts');assert.equal(data.BONES.length,24);assert.equal(new Set(data.BONES.map(b=>b.id)).size,24);\nconst sum=d=>data.BONES.filter(b=>b.division===d).reduce((s,b)=>s+b.count,0);assert.equal(sum('axial'),80);assert.equal(sum('appendicular'),126);\nassert.equal(new Set(Array.from({length:24},(_,i)=>data.challengeBone(i).id)).size,24,'challenge sequence covers all groups');\nconst topic=JSON.parse(fs.readFileSync('src/lib/explorer/topics-data.json','utf8')).find(t=>t.id==='biology-skeletal-system');assert.equal(topic.parameters[0].max,data.BONES.length-1);\nconst {prepare}=load('src/lib/explorer/prepare.ts');for(const language of ['en','yo','ha','ig']){const r=prepare({prompt:'human skeleton',language});assert.equal(r.topicId,topic.id);assert(r.explanation.length>40);assert(r.url.startsWith('/biology/skeletal-system?'));}\nconst {SkeletalActivity}=load('src/components/biology/SkeletalActivity.tsx');\nfunction nodes(tree){const list=[];function walk(n){if(!React.isValidElement(n))return;list.push(n);React.Children.forEach(n.props.children,walk);}walk(tree);return list;}\nconst text=n=>typeof n==='string'||typeof n==='number'?String(n):React.isValidElement(n)?React.Children.toArray(n.props.children).map(text).join(''):'';\nfunction render(){cursor=0;return nodes(SkeletalActivity({embed:false}));}\nlet n=render();n.find(n=>n.type==='select'&&n.props.value==='explore').props.onChange({target:{value:'classify'}});\nn=render();const correct=data.challengeBone(0).division;n.find(n=>n.type==='button'&&text(n)===correct).props.onClick();n=render();assert(n.some(n=>text(n)==='Score: 1/1 first attempts'));assert(n.filter(n=>n.type==='button'&&['axial','appendicular'].includes(text(n))).every(n=>n.props.disabled));\nn.find(n=>n.type==='button'&&text(n)==='Reveal answer').props.onClick();n=render();assert(n.some(n=>text(n)==='Score: 1/1 first attempts'),'reveal cannot score a second attempt');\nn.find(n=>n.type==='button'&&text(n)==='Reset activity').props.onClick();n=render();assert(n.some(n=>n.type==='select'&&n.props.value==='explore'));\nn.find(n=>n.type==='button'&&text(n)==='Scapulae').props.onClick();n=render();const diagram=n.find(n=>n.props.onSelect&&n.props.division==='all'&&n.props.interactive);assert.equal(diagram.props.selected,'scapulae');assert.equal(diagram.props.view,'back');\nconsole.log('PASS: 206-bone group totals, challenge coverage, four explainer languages, score locking/reveal, reset and back-view selection.');\n"},expected={"src/lib/subjects.ts": "537f6b261e9fa733d4260b498838192cfd4f9d27177265a40f1a0688330079d4", "src/lib/explorer/topics-data.json": "6d9cefdaddfa5835d79589c0d24aa2f743a15a22572ec3a21f22c1383c81629d", "src/lib/explorer/locales.ts": "0e52bef74d3a3a74fe6858e41cf27ac6f8dd9b595b14de2b61b3f89ee29ebff0", "src/components/explorer/TopicPicker.tsx": "1d6587c6c266814ef972d43e500b6b37805382db2b89b965d3ed3ecec4ce2696", "src/app/explore/page.tsx": "e8f44a2726321e8d9a1e52f7448a8a0b55f0cc09e59439bc7305d3b9d2224aef", "checks/classroom-controls.cjs": "71fd13667c2757149a0ce56c4161b7b4bea05b80f840db7da24ec21e8c49bfa1", "checks/embed-layout.cjs": "f18b94de54e5a13a22e6e5a6bd848de67416b1a225b1a0249a1a3d2db3aecd0a", "src/lib/biology/languages.ts": null, "src/lib/biology/skeleton.ts": null, "src/components/biology/biology.css": null, "src/components/biology/SkeletonDiagram.tsx": null, "src/components/biology/SkeletalActivity.tsx": null, "src/app/biology/page.tsx": null, "src/app/biology/skeletal-system/page.tsx": null, "src/app/embed/skeletal-system/page.tsx": null, "checks/biology-skeleton.cjs": null};
